const icons={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',skills:'<path d="m12 3 8 5v8l-8 5-8-5V8z"/><path d="m4 8 8 5 8-5m-8 5v8"/>',quests:'<path d="M5 21V3m0 1h13l-3 5 3 5H5"/>',equipment:'<path d="m12 3 8 4-1 9-7 5-7-5-1-9z"/><path d="m8 11 3 3 5-6"/>',rewards:'<rect x="3" y="8" width="18" height="4" rx="1"/><path d="M5 12v9h14v-9M12 8v13M7 8C0 1 9 0 12 8c3-8 12-7 5 0"/>',benchmarks:'<path d="M4 3v18h17M8 16v-5m5 5V6m5 10V9"/>',journal:'<path d="M5 3h14v18H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2Zm0 14h14M8 7h7m-7 4h5"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="m9 5 7 7-7 7"/>',back:'<path d="m15 5-7 7 7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',leaf:'<path d="M20 3C9 2 2 8 5 16c8 4 16-2 15-13ZM4 21 16 8"/>',flame:'<path d="M12 2c2 7 8 8 8 13a8 8 0 0 1-16 0c0-4 3-7 4-8 0 5 4 4 4-5Z"/>',book:'<path d="M12 5C8 2 4 3 2 4v16c4-2 7-1 10 1 3-2 6-3 10-1V4c-2-1-6-2-10 1Zm0 0v16"/>',tool:'<path d="m14 4 1 5 5 1a6 6 0 0 1-8 5l-7 7-3-3 7-7a6 6 0 0 1 5-8Z"/>',heart:'<path d="M12 21 3 12C-2 5 7 0 12 7c5-7 14-2 9 5Z"/>',brain:'<path d="M12 4C6 0 4 5 5 7c-5 0-4 8 0 8-1 6 5 7 7 3 2 4 8 3 7-3 4 0 5-8 0-8 1-2-1-7-7-3Zm0 0v14M5 7l3 2m11-2-3 2"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c-6 4-6 14 0 18 6-4 6-14 0-18Z"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12c6 4 12 4 18 0m-9 1v3"/>',camera:'<path d="M3 7h4l2-3h6l2 3h4v14H3Z"/><circle cx="12" cy="13" r="4"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',mountain:'<path d="m2 20 7-13 4 6 3-10 6 17ZM7 11l3 3 2-2m2-3 3 2 1-2"/>'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.skills}</svg>`;
