const empty=(title,description,action='')=>`<div class="empty">${icon('spark')}<h3>${title}</h3><p>${description}</p>${action}</div>`;
const option=(value,label,selected)=>`<option value="${e(value)}"${value===selected?' selected':''}>${e(label)}</option>`;
const categoryName=id=>CATEGORIES.find(c=>c.id===id)?.name||'Personal skill';
const skillOptions=id=>allSkills(state).map(s=>option(s.id,s.name,id)).join('');
const formError='<p class="error-message" role="alert"></p>';
const today=()=>E.dayKey(new Date(),state?.profile.timeZone);
let state=null,p=null,view='dashboard',detailId=null,busy=false,blocked=false,toastTimer,photoUrls=new Map(),search='',category='all',skillFilter='interests',skillPage=0,questFocus='balanced',rewardFilter='available',rewardPage=0,inventoryPage=0,journalPage=0,restorePayload=null,restoreRevision=null,storageInfo=null,installPrompt=null,suggestionOffset=0;
const navItems=[['dashboard','Overview'],['skills','Skills'],['quests','Quests'],['equipment','Equipment'],['rewards','Reward shop'],['benchmarks','Life metrics'],['journal','Milestones'],['settings','Character & data']];
const channel='BroadcastChannel' in window?new BroadcastChannel('human-rpg-character'):null;
channel?.addEventListener('message',event=>{if(state&&event.data.revision!==state.revision){blocked=true;render();toast('A newer save exists in another tab. Reload to continue.',true);}});
function toast(message,error=false){clearTimeout(toastTimer);const el=$('#toast');el.textContent=message;el.className='visible'+(error?' error':'');toastTimer=setTimeout(()=>el.className='',6000);}
function dialog(title,body,wide=false){const d=$('#modal');d.className=wide?'wide':'';d.innerHTML=`<div class="dialog-header"><h2 id="dialog-title">${title}</h2><button type="button" class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!d.open)d.showModal();hydratePhotos();}
const closeDialog=()=>$('#modal').close();
function showError(error,form){const message=error?.message||'Your last saved character is retained.';if(form?.querySelector('.error-message'))form.querySelector('.error-message').textContent=message;else toast(message,true);}
async function mutate(fn,message){
 if(blocked)throw Error('Reload this tab to use the latest character. No changes were saved.');
 if(busy)throw Error('A save is already in progress. Please try again.');busy=true;
 try{const next=E.clone(state);E.settleQuests(next);await fn(next);E.resolveRewards(next);state=await DB.saveState(next,state.revision);channel?.postMessage({revision:state.revision});p=E.project(state);render();if(message)toast(message);return true;}
 catch(err){if(err.name==='ConflictError'){blocked=true;render();}throw err;}finally{busy=false;}
}
function navButtons(mobile=false){return (mobile?[navItems[0],navItems[1],navItems[2],navItems[3],['more','More']]:navItems).map(([id,label])=>`<button type="button" data-action="${id==='more'?'more':'nav'}" data-view="${id}" class="${view===id||(id==='skills'&&view==='skill')?'selected':''}" ${view===id?'aria-current="page"':''}>${icon(id)}<span>${label}</span>${!mobile&&id==='equipment'&&state.gearOffers.some(o=>!o.claimed)?`<span class="badge">${state.gearOffers.filter(o=>!o.claimed).length}</span>`:''}</button>`).join('');}
function render(){
 if(!state){renderOnboarding();return;}p=E.project(state);
 const title=navItems.find(([id])=>id===view)?.[1]||(view==='skill'?'Skills':'Overview'),cl=CLASSES.find(c=>c.id===state.profile.classId)||CLASSES[0];
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand flex"><span class="brand-mark">H</span><div><strong>Human RPG</strong><small>A life in progress</small></div></div><div class="nav-label">Your journey</div><nav class="nav" aria-label="Main navigation">${navButtons()}</nav><div class="sidebar-bottom"><div class="save-status"><span class="status-dot"></span>${blocked?'Newer save in another tab':'Saved on this device'}</div><div class="mini-character"><div class="avatar">${e(state.profile.name.charAt(0).toUpperCase())}</div><div class="grow"><strong class="small" style="color:var(--text)">${e(state.profile.name)}</strong><div class="small">Lv. ${p.characterLevel} · ${cl.name}</div></div></div><div class="small mt" style="font-size:9px">Human RPG · v${VERSION}</div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">Your journey <span style="margin:0 12px;color:#64747b">/</span><span>${title}</span></div><div class="mobile-brand"><span class="brand-mark">H</span>Human RPG</div><div class="top-actions"><span class="date-label muted">${new Date().toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',timeZone:state.profile.timeZone})}</span><span class="gold"><span class="coin">R</span>${num(p.creditsCents/100)} <span class="muted">credits</span></span>${btn(icon('plus')+' Log activity','log','','small')}</div></header><main id="main" class="content" tabindex="-1">${blocked?`<div class="callout warning">Another tab has a newer save. Reload before making changes. ${btn('Reload','reload','','small')}</div>`:''}${renderView()}</main></div><nav class="mobile-nav" aria-label="Mobile navigation">${navButtons(true)}</nav></div>`;
 hydratePhotos();
}
function renderOnboarding(){
 $('#app').innerHTML=`<main id="main" class="onboarding"><div class="brand flex"><span class="brand-mark">H</span><div><strong>Human RPG</strong><small>A life in progress</small></div></div><div class="welcome-grid"><section class="welcome-copy"><div class="eyebrow">The adventure is already yours</div><h1>Build a life.<br><em>Become a legend.</em></h1><p>Your skills. Your quests. Your next chapter. Turn the things you practice into progress you can see—and milestones worth remembering.</p><div class="welcome-rule"></div><div class="welcome-features"><div class="welcome-feature">${icon('skills')} ${SKILLS.length} skills. Fifty levels. A lifetime of possibility.</div><div class="welcome-feature">${icon('quests')} Earn the next level with a real challenge.</div><div class="welcome-feature">${icon('lock')} Your story stays here, on your device.</div></div></section><section class="card onboard-card"><div class="eyebrow">Create your character</div><h2>Every story starts somewhere.</h2><form id="onboard-form"><label class="field"><span>What should we call you?</span><input name="name" maxlength="80" placeholder="Your character name" autocomplete="given-name" required></label><label class="field"><span>Your primary class</span><select name="classId">${CLASSES.map(c=>option(c.id,c.name+' · '+c.subtitle,'explorer')).join('')}</select><small>Your job or role. You can change this later.</small></label><label class="field"><span>Total annual personal income <span class="muted">(optional)</span></span><input type="number" name="income" min="0" max="1000000000000" step=".01" placeholder="USD / year" inputmode="decimal"><small>Sets the scale of self-funded rewards. Includes income beyond salary.</small></label><div class="form-actions"><button class="btn primary" name="path" value="quick" type="submit">Quick start ${icon('arrow')}</button><button class="btn ghost" name="path" value="assess" type="submit">Assess my existing skills</button></div><p class="field-hint" style="text-align:center;margin:13px 0 0">Quick start begins at level 0. Assess any skill later.</p>${formError}</form><div class="divider"></div><button type="button" class="btn text" data-action="import">${icon('download')} Restore a saved character</button></section></div><footer><span>Built for real life. Kept private by design.</span><span>v${VERSION} · Back up your story in Settings</span></footer></main>`;
}
const head=(title,description,action='')=>`<div class="page-head"><div><div class="eyebrow">Your journey / ${e(view==='skill'?'Skills':navItems.find(n=>n[0]===view)?.[1]||'Overview')}</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;
function renderView(){return ({dashboard,skills:skillsView,skill:skillView,quests:questsView,equipment:equipmentView,rewards:rewardsView,benchmarks:benchmarksView,journal:journalView,settings:settingsView}[view]||dashboard)();}
function topSkills(){return allSkills(state).filter(s=>p.skills[s.id].level>0||state.profile.interests.includes(s.category)).sort((a,b)=>p.skills[b.id].effective-p.skills[a.id].effective||a.name.localeCompare(b.name));}
function skillRow(s){const k=p.skills[s.id];return `<div class="skill-row"><div class="skill-icon ${s.attribute==='Intellect'?'purple':''}">${skillIcon(s)}</div><div class="grow"><button class="btn text" data-action="skill" data-id="${e(s.id)}" style="color:var(--text);padding:0;min-height:0"><strong>${e(s.name)}</strong></button><div class="flex between small" style="font-size:10px"><span>${rankName(k.level)}${k.legendary?' · +'+k.legendary+' legendary':''}</span><span>${Math.round(k.progress*100)}%</span></div>${bar(k.progress)}</div><div class="rank">${k.effective}<div class="small" style="font-size:9px">/ 50</div></div></div>`;}
function attributesPanel(){return `<div class="card"><div class="card-title"><h2>Your attributes</h2><span class="pill gold">${p.freeAttributePoints} to assign</span></div><div class="attributes">${ATTRIBUTES.map(a=>`<div class="attribute"><span class="attr-code">${a.slice(0,3).toUpperCase()}</span><div><div class="name">${a}</div>${bar(Math.min(1,p.attributes[a]/70),'gold')}</div><span class="number">${p.attributes[a]}</span>${p.freeAttributePoints?`<button class="icon-btn" data-action="attribute" data-id="${a}" aria-label="Assign one point to ${a}">${icon('plus')}</button>`:'<span></span>'}</div>`).join('')}</div><p class="source-note">Trained skills shape your stats. Gain one free point every five character levels.</p></div>`;}
function dashboard(){
 const trained=Object.values(p.skills).filter(k=>k.level>0).length,logged=state.activities.filter(a=>!a.voided&&a.kind!=='quest'&&a.date===today()).length,active=state.quests.filter(q=>q.status==='active'),cl=CLASSES.find(c=>c.id===state.profile.classId)||CLASSES[0];
 const ready=allSkills(state).filter(s=>{const k=p.skills[s.id];return k.level<50&&E.xp(k.xp)>=E.threshold(k.level+1);});
 return `${head('Welcome back, '+e(state.profile.name)+'.','A little intention. A little practice. A life well lived.',btn(icon('quests')+' Find a quest','nav','data-view="quests"','ghost'))}<section class="card hero"><svg class="hero-art" viewBox="0 0 400 320" fill="none" aria-hidden="true"><circle cx="250" cy="130" r="100" stroke="currentColor"/><circle cx="250" cy="130" r="115" stroke="currentColor"/><circle cx="250" cy="130" r="130" stroke="currentColor"/><path d="m10 310 100-180 65 70L250 60l145 250M80 310l90-170 43 55 38-45 95 160" stroke="currentColor" stroke-width="2"/><path d="m210 135 40-75 43 85-40-25z" fill="currentColor" opacity=".5"/></svg><div class="level-medallion"><span>Level</span><strong>${p.characterLevel}</strong><span>${rankName(p.characterLevel).split(' ')[0]}</span></div><div class="hero-copy"><div class="eyebrow">${cl.name} · Chapter ${Math.floor(p.characterLevel/10)+1}</div><h2>${p.characterLevel===0?'The first step changes everything.':'Your next chapter is earned.'}</h2><p>${p.characterLevel===0?'Choose something that matters. Practice it. Make a little room for the person you want to become.':'Keep building what matters to you. Your experience tells a story that a single number never could.'}</p><div class="hero-bottom"><div class="grow">${bar(p.characterProgress,'gold large')}</div><span class="small mono gold">${E.formatXP(p.characterXP)} / ${p.characterLevel===50?'MAX':E.formatXP(E.threshold(p.characterLevel+1,true))} XP</span></div></div></section><div class="stat-grid">${[[icon('skills')+' Skills in practice',trained,'/ '+allSkills(state).length,'Every skill is tracked'],[icon('quests')+' Active quests',active.length,'in progress',state.quests.filter(q=>q.status==='completed').length+' completed so far'],[icon('flame')+" Today's activity",logged,'entries','Practice makes progress'],[icon('rewards')+' Reward credits',num(p.creditsCents/100),'','Your earned spending permission']].map(([label,value,unit,note])=>`<div class="card stat-card"><div class="stat-label">${label}</div><div class="value">${value}<small>${unit}</small></div><div class="stat-note">${note}</div></div>`).join('')}</div>${ready.length?`<div class="callout success flex between wrap"><span>${ready.length} skills have enough XP for a promotion challenge.</span>${btn('View challenge','skill','data-id="'+ready[0].id+'"','small')}</div>`:''}<div class="two-col"><div class="stack"><section class="card"><div class="card-title"><h2>Skills on your path</h2>${btn('Explore all →','nav','data-view="skills"','text small')}</div>${topSkills().slice(0,5).map(skillRow).join('')}<p class="source-note mt">Interests shape this view. Your other skills are always here.</p></section><section class="card"><div class="card-title"><h2>Recent chapters</h2>${btn('View journal →','nav','data-view="journal"','text small')}</div>${recentActivity(3)}</section></div><div class="stack"><section class="card"><div class="card-title"><h2>${active.length?'Your next moves':'A quest to get you going'}</h2>${icon('quests','gold')}</div>${active.length?active.slice(0,2).map(questCard).join(''):suggestionCard(getSuggestions()[0])}</section>${attributesPanel()}<div class="callout" style="margin:0"><strong class="gold">Keep a copy of your story.</strong><p class="small" style="margin-top:6px">Progress and photos live in this browser. Export a backup for safekeeping or a new device.</p>${btn('Save a backup','export','','text small')}</div></div></div>`;
}
function skillsView(){
 let list=allSkills(state).filter(s=>(category==='all'||s.category===category)&&(!search||(s.name+' '+s.specialties.join(' ')).toLowerCase().includes(search.toLowerCase()))&&(skillFilter==='all'||(skillFilter==='interests'?state.profile.interests.includes(s.category):skillFilter==='trained'?p.skills[s.id].level>0:E.xp(p.skills[s.id].xp)>=E.threshold(Math.min(50,p.skills[s.id].level+1))&&p.skills[s.id].level<50)));
 const maxPage=Math.max(0,Math.ceil(list.length/24)-1);skillPage=Math.min(skillPage,maxPage);
 return `${head('The skill atlas',allSkills(state).length+' skills. Fifty levels each. Follow your curiosity.',btn(icon('plus')+' Add a skill','custom-skill','','ghost'))}<div class="filters"><input id="skill-search" aria-label="Search skills and specialties" placeholder="Search skills or specialties…" value="${e(search)}"><select id="category-filter" aria-label="Filter category">${option('all','All categories',category)}${CATEGORIES.map(c=>option(c.id,c.name,category)).join('')}</select><select id="skill-filter" aria-label="Filter skill status">${[['interests','My interests'],['all','All skills'],['trained','With progress'],['ready','Challenge ready']].map(([v,l])=>option(v,l,skillFilter)).join('')}</select></div><div class="flex between mb"><span class="small">${list.length} skills in view</span>${btn('Edit interests','interests','','text small')}</div><div class="skill-grid">${list.slice(skillPage*24,(skillPage+1)*24).map(s=>{const k=p.skills[s.id];return `<button type="button" class="card skill-card" data-action="skill" data-id="${e(s.id)}"><span class="skill-icon ${s.attribute==='Intellect'?'purple':''}">${skillIcon(s)}</span><div class="skill-rank">${k.effective}<span>Level</span></div><h3>${e(s.name)}</h3><p>${e(categoryName(s.category))}</p>${bar(k.progress)}<footer><span>${rankName(k.level)}</span><span>${k.legendary?'+'+k.legendary+' legendary':k.assessed&&!k.passed?'Assessed':E.formatXP(k.xp)+' XP'}</span></footer></button>`;}).join('')}</div>${!list.length?empty('A new direction awaits.','Try another filter or add a skill of your own.'):''}${maxPage>0?pagination('skill',skillPage,maxPage):''}`;
}
function pagination(kind,page,max){return `<div class="pagination">${btn('Previous',kind+'-page','data-delta="-1" '+(page===0?'disabled':''),'small ghost')}<span class="small">${page+1} / ${max+1}</span>${btn('Next',kind+'-page','data-delta="1" '+(page===max?'disabled':''),'small ghost')}</div>`;}
function skillView(){
 const s=skillById(state,detailId);if(!s)return empty('Skill not found','Return to the atlas.',btn('All skills','nav','data-view="skills"'));
 const k=p.skills[s.id],validation=k.assessed>k.passed&&k.level>0,rank=validation?k.level:Math.min(50,k.level+1),ready=E.xp(k.xp)>=E.threshold(rank),challenge=challengeFor(s,rank),pending=state.attempts.find(a=>a.skillId===s.id&&a.rank===rank&&!a.passed),passed=state.attempts.filter(a=>a.skillId===s.id&&a.passed).sort((a,b)=>b.rank-a.rank);
 return `${btn(icon('back')+' Back to skills','nav','data-view="skills"','text back-link')}<div class="detail-hero"><div class="skill-icon">${skillIcon(s)}</div><div class="grow"><div class="eyebrow">${e(categoryName(s.category))} / ${e(s.attribute)}</div><h1>${e(s.name)}</h1><p>${e(s.specialties.join(' · '))}</p></div>${btn(icon('plus')+' Practice','log','data-id="'+e(s.id)+'"','primary')}</div><div class="stat-grid">${[['Current skill',k.level,rankName(k.level)],['Effective level',k.effective,k.legendary?'+'+k.legendary+' from one legendary source':'No legendary bonus'],['Peak / passed gateway',k.ceiling+' / '+k.passed,'Gateways are kept forever'],['Current XP',E.formatXP(k.xp),E.formatXP(k.lostXp)+' XP drained over time']].map(([label,value,note])=>`<div class="card stat-card"><div class="stat-label">${label}</div><div class="value">${value}</div><div class="stat-note">${note}</div></div>`).join('')}</div><div class="two-col"><div class="stack"><section class="card"><div class="card-title"><h2>${validation?'Validate your experience':k.level===50?'A place in the history books':'Your level '+rank+' challenge'}</h2><span class="pill gold">${ready?'XP ready':'In progress'}</span></div><h3>${e(challenge.title)}</h3><p>${e(challenge.objective)}</p>${bar(k.level===50?1:Math.min(1,Number(E.xp(k.xp)*10000n/E.threshold(rank))/10000),'gold')}<div class="flex between small mt"><span>${E.formatXP(k.xp)} / ${E.formatXP(E.threshold(rank))} XP</span><span>Level ${rank}</span></div><div class="form-actions">${k.level<50||validation?btn(pending?'Continue challenge':validation?'Validate this level':'Start challenge','challenge','data-id="'+e(s.id)+'" data-rank="'+rank+'" '+(!ready?'disabled':''),'primary'):''}${!k.level&&!state.activities.some(a=>a.skillId===s.id&&!a.voided)?btn('Assess existing skill','assess','data-id="'+e(s.id)+'"','ghost'):''}</div><p class="source-note">${e(challenge.coverage)}. The rubric appears after your first completion claim.</p></section><section class="card"><div class="card-title"><h2>Practice history</h2></div>${recentActivity(12,s.id)}</section></div><div class="stack"><section class="card"><h2>A lifetime of progression</h2><div class="milestone-strip">${[[1,'Foundation'],[10,'Practitioner'],[20,'Accomplished'],[30,'Expert'],[40,'World class'],[50,'Historic']].map(([l,n])=>`<div class="milestone-step ${k.effective>=l?'reached':''}"><strong>${l}</strong>${n}</div>`).join('')}</div><p class="small">Level 50 represents sustained best-in-world achievement. An accomplished amateur can spend a rewarding lifetime in the twenties.</p>${k.legendary?'<div class="callout">A legendary bonus earns combined-level rewards. It is not proof of a competitive title.</div>':''}</section><section class="card"><h2>Keep it in practice</h2><p class="small">Base daily drain: <strong class="gold">${E.formatXP(minTaskXP(k.level))} XP</strong>, before equipment protection.</p><p class="small">XP pauses at the next lower level’s threshold during the grace period. If XP remains low, the next inactivity demotion is due ${fmtDate(k.nextDemotion)}.</p><p class="small">New skill XP resets the three-month clock. Recovering a passed level never requires its challenge again.</p></section><section class="card"><h2>Milestones preserved</h2>${passed.length?passed.slice(0,5).map(a=>`<div class="skill-row"><span class="pill gold">Lv. ${a.rank}</span><div class="grow"><strong>${fmtDate(a.passedAt)}</strong><div class="small">${e(a.notes?.slice(0,85)||'Challenge completed')}</div></div>${btn('View','attempt','data-id="'+e(a.id)+'"','text small')}</div>`).join(''):empty('Your first milestone is ahead.','Challenge notes and photos will be kept here, even if a skill later decays.')}</section><section class="card" id="skill-standards"><h2>Real-world standards</h2><p class="small">See competition rankings, proficiency frameworks, and available population data for this discipline.</p>${btn('View ranking sources','rankings','data-id="'+e(s.id)+'"','small')}</section></div></div>`;
}
function recentActivity(limit,skillId){
 const list=state.activities.filter(a=>!a.voided&&(!skillId||a.skillId===skillId)).sort((a,b)=>b.date.localeCompare(a.date)||b.loggedAt.localeCompare(a.loggedAt)).slice(0,limit);
 return list.length?`<div class="log-list">${list.map(a=>`<div class="log-entry"><div class="date-block">${new Date(a.date+'T12:00Z').toLocaleDateString('en-US',{month:'short',timeZone:'UTC'})}<strong>${a.date.slice(-2)}</strong></div><div class="grow"><div class="flex between wrap"><h3>${e(a.title)}</h3><span class="gold small">+${E.formatXP(p.awards.get(a.id)||0n)} XP</span></div><p>${e(skillById(state,a.skillId)?.name)}${a.late?' · late entry, half base XP':''}${a.minutes?' · '+a.minutes+' min':''}</p>${a.notes?'<p>'+e(a.notes.slice(0,180))+'</p>':''}<div class="photos">${(a.photos||[]).map(photoThumb).join('')}</div>${a.kind!=='quest'?btn('View entry','entry','data-id="'+e(a.id)+'"','text small'):''}</div></div>`).join('')}</div>`:empty('Make your first mark.','Log practice, a meaningful outcome, or a completed project.',btn('Log activity','log',skillId?'data-id="'+e(skillId)+'"':'','small'));}
function getSuggestions(){
 let list=allSkills(state).filter(s=>state.profile.interests.includes(s.category));if(!list.length)list=allSkills(state);
 if(questFocus==='class'){const cls=CLASSES.find(c=>c.id===state.profile.classId);list=allSkills(state).filter(s=>!cls.categories.length||cls.categories.includes(s.category));}
 if(questFocus==='strong')list.sort((a,b)=>p.skills[b.id].level-p.skills[a.id].level||a.name.localeCompare(b.name));
 if(questFocus==='weak')list=list.filter(s=>p.skills[s.id].level>0).sort((a,b)=>p.skills[a.id].level-p.skills[b.id].level);
 if(!list.length)return [];const offset=suggestionOffset%list.length;
 return [...list.slice(offset),...list.slice(0,offset)].slice(0,3).map(s=>{
 const kind=['computing','science','thinking','communication'].includes(s.category)?'study':['career','business','trades','home','creative','finance'].includes(s.category)?'outcome':'practice';
 return {skillId:s.id,title:(kind==='study'?'Spend focused time on ':kind==='outcome'?'Deliver something with ':'Make time for ')+s.name.toLowerCase(),target:kind==='study'?60:kind==='outcome'?2:3,metric:kind==='study'?'minutes':kind==='outcome'?'units':'sessions',rank:Math.max(1,p.skills[s.id].level),mode:'timed',deadline:E.dayFromNumber(E.dayNumber(today())+7)};});
}
function suggestionCard(q){
 if(!q)return empty('Nothing to rank yet.','Assess or practice a skill to identify your relative strengths and areas to develop.',btn('Explore skills','nav','data-view="skills"','small'));
 const s=skillById(state,q.skillId);
 return `<article class="quest-tile"><div class="flex between"><span class="pill">${e(s.name)}</span><span class="small">${icon('clock')} 7 days</span></div><h3>${e(q.title)}</h3><p>Complete ${q.target} ${q.metric==='minutes'?'minutes of focused practice':q.metric==='units'?'meaningful outcome units':'intentional practice sessions'}. Activity difficulty ${Math.max(0,q.rank-1)}+ qualifies.</p><div class="quest-reward">${icon('spark')} ${E.formatXP(minTaskXP(q.rank)*5n)} XP <span>+ ${num(Math.round(E.rewardCents(q.rank,state.profile.annualIncomeCents)*.05)/100)} credits</span></div><div class="flex between">${btn('Accept quest','accept-suggestion','data-id="'+e(q.skillId)+'"','small primary')}${btn('Replace','replace-suggestion','','small text')}</div></article>`;
}
function questCard(q){
 const current=E.questProgress(state,q),ready=current>=q.target&&q.status==='active';
 return `<article class="quest-tile"><div class="flex between wrap"><span class="pill ${q.mode==='commitment'?'purple':''}">${q.mode==='commitment'?'Commitment':q.mode==='timed'?'Timed quest':'Open quest'}</span><span class="small">${q.deadline?'Due '+fmtDate(q.deadline):'Your own pace'}</span></div><h3>${e(q.title)}</h3><p>${e(skillById(state,q.skillId)?.name)} · ${num(current)} / ${num(q.target)} ${e(q.metric)} · difficulty ${q.minTier||0}+</p>${bar(Math.min(1,current/q.target))}<div class="quest-reward">${E.formatXP(q.rewardXP)} XP <span>+ ${num(q.rewardCents/100)} credits</span></div>${q.stakeCents?`<p class="small gold">${num(q.stakeCents/100)} credits ${['completed','voided'].includes(q.status)?'returned':q.status==='active'?'reserved':'forfeited'}</p>`:''}<div class="flex between wrap">${q.status==='active'?`${ready?btn('Claim completion','complete-quest','data-id="'+q.id+'"','small primary'):btn('Log progress','log','data-id="'+e(q.skillId)+'"','small')}${q.mode==='open'?btn('Pause','pause-quest','data-id="'+q.id+'"','text small'):''}${btn('Abandon','abandon-quest','data-id="'+q.id+'"','text small')}`:q.status==='paused'?btn('Resume quest','pause-quest','data-id="'+q.id+'"','small'):`<span class="pill ${q.status==='completed'?'':'red'}">${e(q.status)}</span>`}</div>${q.status==='completed'?btn('Correct completion','void-quest','data-id="'+e(q.id)+'"','text small'):''}</article>`;
}
function questsView(){const active=state.quests.filter(q=>['active','paused'].includes(q.status)),closed=state.quests.filter(q=>!['active','paused'].includes(q.status)).slice().reverse();return `${head('The quest board','Make a promise to your future self. Then follow through.',btn(icon('plus')+' Create quest','quest-form','','primary'))}<div class="two-col"><section class="card"><div class="card-title"><h2>In your quest log</h2><span class="pill gold">${active.length} active / paused</span></div>${active.length?active.map(questCard).join(''):empty('Choose your next small adventure.','Accept a suggestion or set a goal of your own. Quests reward work logged after you accept them.',btn('Create a quest','quest-form','','small'))}${closed.length?`<details class="disclosure mt"><summary>${closed.length} completed or closed quests</summary><div class="mt">${closed.slice(0,15).map(questCard).join('')}</div></details>`:''}</section><div class="stack"><section class="card"><div class="card-title"><h2>Choose a direction</h2>${icon('quests','gold')}</div><div class="chips mb">${[['balanced','Explore'],['strong','Strengths'],['weak','Develop'],['class','My class']].map(([v,l])=>`<button class="chip ${questFocus===v?'active':''}" data-action="quest-focus" data-value="${v}">${l}</button>`).join('')}</div><p class="small">${questFocus==='weak'?'Your lower trained skill levels. Unassessed skills are not treated as weaknesses.':questFocus==='strong'?'Build on your strongest trained skills.':questFocus==='class'?'Goals related to your current class. Its XP bonus applies to qualifying work.':'Find something interesting in your chosen categories.'}</p>${getSuggestions().map(suggestionCard).join('')}</section><div class="callout"><strong class="gold">A little accountability goes a long way.</strong><p class="small" style="margin-top:7px">Timed quests lose their completion bonus if the deadline passes. Commitment quests also put a chosen number of credits at stake. You’ll see and accept the terms first.</p></div></div></div>`;}
function effectText(item){return item.effect==='hiking-day'?'+5% all-day XP on days you log at least 5 miles hiking':item.effect==='decay'?item.bps/100+'% less daily '+(item.skillId==='character'?'all skills':skillById(state,item.skillId)?.name||'skill')+' XP drain':'+'+item.bps/100+'% '+(item.skillId==='character'?'all skills':skillById(state,item.skillId)?.name||'skill')+' activity XP';}
function equipmentView(){
 const pending=state.gearOffers.filter(o=>!o.claimed),items=state.inventory;
 return `${head('Tools of your becoming','Earned through real challenges. Equipped for what comes next.')}<div class="equal-col"><section class="card"><div class="card-title"><h2>Your loadout</h2><span class="small">${Object.values(state.equipment).filter(Boolean).length} / 10 equipped</span></div><div class="equipment-stage"><svg class="silhouette" viewBox="0 0 200 380" fill="none" aria-hidden="true"><circle cx="100" cy="58" r="26" fill="#8f9c7d22" stroke="#e4bb7788"/><path d="M74 91h52l25 42 12 98-17 3-22-85-3 75 15 128-25 5-11-113-11 113-25-5 15-128-3-75-22 85-17-3 12-98z" fill="#8f9c7d12" stroke="#e4bb7766"/><path d="M100 95v137M76 148h48m-46 61h44" stroke="#e4bb7733"/><ellipse cx="100" cy="369" rx="63" ry="7" fill="#e4bb7711"/><circle cx="100" cy="176" r="85" stroke="#8bd3be15"/></svg>${SLOTS.map(slot=>{const item=items.find(i=>i.id===state.equipment[slot]),lock=item&&E.lockedUntil(state,item.id);return `<button class="slot ${item?'filled':''} ${lock?'locked':''}" data-action="slot" data-id="${slot}"><span class="slot-label">${icon(lock?'lock':'equipment')} ${SLOT_LABELS[slot]}</span><strong>${item?e(item.name.split(' · ')[0]):'Empty slot'}</strong>${lock?`<span class="lock-label">${Math.max(1,Math.ceil((Date.parse(lock)-Date.now())/86400000))} days locked</span>`:''}</button>`;}).join('')}</div><p class="small">Passive effects apply while equipped. Activating an ability locks its item and slot for all 30 days of its cooldown.</p></section><section class="card"><div class="card-title"><h2>Choose your spoils</h2><span class="pill gold">${pending.length} choices</span></div>${pending.length?pending.slice(0,6).map(o=>`<div class="quest-tile"><span class="pill gold">Level ${o.rank} · ${SLOT_LABELS[o.slot]}</span><h3>${e(o.skillName)} reward</h3><p>Choose a bonus to practice XP or protection against daily decay.${o.rank%5===0?' Includes a one-day active ability.':''}</p>${btn('Choose your item','gear-choice','data-id="'+e(o.id)+'"','small primary')}</div>`).join('')+(pending.length>6?'<p class="small">'+(pending.length-6)+' more choices follow these.</p>':''):empty('Great tools are earned.','Pass a promotion challenge to choose skill-themed gear. Validating a higher assessed level also grants its earlier rewards.')}</section></div><section class="mt"><div class="card-title"><h2>Your inventory</h2><span class="small">${items.length} items</span></div>${items.length?`<div class="inventory-grid">${items.slice(inventoryPage*20,(inventoryPage+1)*20).map(item=>`<article class="card item-card"><div class="flex between"><span class="skill-icon gold">${icon('equipment')}</span><span class="pill gold">Lv. ${item.rank}</span></div><h3>${e(item.name)}</h3><p>${SLOT_LABELS[item.slot]}${item.active?' · Active ability':''}</p><div class="effect">${e(effectText(item))}</div><div class="mt">${btn(Object.values(state.equipment).includes(item.id)?'Equipped · details':'Equip / details','item','data-id="'+e(item.id)+'"','small ghost')}</div></article>`).join('')}</div>${items.length>20?pagination('inventory',inventoryPage,Math.ceil(items.length/20)-1):''}`:empty('A little room for future treasures.','Your first promotion challenge is the start of your collection.')}</section>`;
}
const shopOffers=()=>[{key:'shop:focus',id:'shop:focus',skillId:topSkills()[0]?.id||'cooking',skillName:topSkills()[0]?.name||'Cooking',name:'Everyday Focus Headphones',rank:5,slot:'head',variant:0,priceCents:2500},{key:'shop:keeper',id:'shop:keeper',skillId:topSkills()[0]?.id||'cooking',skillName:topSkills()[0]?.name||'Cooking',name:'Practice Keeper Notebook',rank:10,slot:'off',variant:1,priceCents:10000},{key:'shop:master',id:'shop:master',skillId:topSkills()[0]?.id||'cooking',skillName:topSkills()[0]?.name||'Cooking',name:'Masterwork Signature Tool',rank:40,slot:'main',variant:0,priceCents:100000}];
