async function photosFrom(form){const files=[...form.elements.photos?.files||[]];if(files.length>8)throw Error('Attach up to eight photos at a time.');const ids=[];for(const f of files)ids.push(await DB.storePhoto(f));return ids;}
function download(text,name,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
async function exportBackup(){
 if(!state)throw Error('Create or restore a character first.');
 const at=new Date().toISOString(),copy=E.clone(state);copy.lastBackupAt=at;const text=await DB.makeBackup(copy);
 download(text,'human-rpg-'+today()+'.json');await mutate(s=>{s.lastBackupAt=at;},'Full backup downloaded, including attached photos.');
}
async function prepareRestore(file){
 restorePayload=await DB.readBackup(file);restoreRevision=state?.revision??await DB.currentRevision();const incoming=restorePayload.state;
 dialog('Review this restore',`<div class="callout warning"><strong>This replaces the character currently on this device.</strong> Changes made after the backup will not be in the restored character. A local pre-restore copy is kept; use “Undo last restore” in Settings to recover it. Export a backup first if you want an independent copy.</div><div class="quest-tile"><span class="pill gold">Backup v${e(restorePayload.version)}</span><h3>${e(incoming.profile.name)}</h3><p>Exported ${fmtDate(restorePayload.exportedAt)}<br>${incoming.activities.length} activity entries · ${incoming.attempts.length} attempts · ${restorePayload.photos.length} photos</p></div>${state?btn('Export current character first','export','','ghost'):''}<form id="restore-form"><label class="check mt"><input type="checkbox" name="confirmed" required><span>I understand this replaces the current character and know where to find the recovery copy.</span></label>${formError}<div class="form-actions">${btn('Cancel','close','','ghost')}<button class="btn primary" type="submit">Restore this backup</button></div></form>`);
}
document.addEventListener('click',async event=>{
 const button=event.target.closest('[data-action]');if(!button||button.disabled)return;
 try{await action(button.dataset.action,button.dataset);}catch(err){showError(err,$('#modal[open] form'));}
});
async function action(action,d){
 switch(action){
 case 'close':closeDialog();return;
 case 'reload':location.reload();return;
 case 'nav':view=d.view;detailId=null;closeDialog();render();window.scrollTo(0,0);$('#main')?.focus({preventScroll:true});return;
 case 'more':dialog('Your journey','<nav class="nav more-nav">'+navButtons()+'</nav>');return;
 case 'skill':detailId=d.id;view='skill';closeDialog();render();window.scrollTo(0,0);return;
 case 'log':logDialog(d.id);return;
 case 'interests':interestsDialog();return;
 case 'assess':assessmentDialog(d.id);return;
 case 'character-assess':characterDialog();return;
 case 'profile':profileDialog();return;
 case 'skill-page':skillPage+=Number(d.delta);render();window.scrollTo(0,0);return;
 case 'reward-page':rewardPage+=Number(d.delta);render();return;
 case 'inventory-page':inventoryPage+=Number(d.delta);render();return;
 case 'journal-page':journalPage+=Number(d.delta);render();return;
 case 'attribute':await mutate(s=>E.allocatePoint(s,d.id),'Attribute point assigned.');return;
 case 'challenge':challengeDialog(d.id,Number(d.rank));return;
 case 'attempt':{const a=state.attempts.find(a=>a.id===d.id);if(a)challengeDialog(a.skillId,a.rank,a.id);return;}
 case 'quest-form':questDialog();return;
 case 'quest-focus':questFocus=d.value;suggestionOffset=0;render();return;
 case 'replace-suggestion':suggestionOffset++;render();return;
 case 'accept-suggestion':{const q=getSuggestions().find(q=>q.skillId===d.id);if(!q)throw Error('Refresh these quest suggestions.');await mutate(s=>{if(s.quests.some(x=>x.skillId===q.skillId&&x.title===q.title&&x.status==='active'))throw Error('This quest is already in your log.');E.createQuest(s,q);},'Quest accepted. Your next activity counts toward it.');return;}
 case 'complete-quest':await mutate(s=>E.completeQuest(s,d.id),'Quest completed. XP and credits awarded.');return;
 case 'pause-quest':await mutate(s=>E.toggleQuestPause(s,d.id),'Quest updated.');return;
 case 'abandon-quest':{const q=state.quests.find(q=>q.id===d.id);dialog('Close this quest?',`<p>${e(q.title)}</p><div class="callout ${q.stakeCents?'warning':''}">${q.stakeCents?num(q.stakeCents/100)+' reserved credits will be forfeited. This cannot be undone.':'The completion bonus will no longer be available.'} Activity XP already earned is retained.</div><div class="form-actions">${btn('Keep quest','close','','ghost')}${btn('Abandon quest','confirm-abandon','data-id="'+e(q.id)+'"','danger')}</div>`);return;}
 case 'confirm-abandon':await mutate(s=>E.abandonQuest(s,d.id),'Quest closed.');closeDialog();return;
 case 'slot':{const item=state.inventory.find(i=>i.id===state.equipment[d.id]);if(item){itemDialog(item.id);return;}const list=state.inventory.filter(i=>i.slot===d.id);dialog(SLOT_LABELS[d.id],list.length?list.map(i=>`<div class="quest-tile"><h3>${e(i.name)}</h3><p>${e(effectText(i))}</p>${btn('Details / equip','item','data-id="'+e(i.id)+'"','small')}</div>`).join(''):empty('This slot is waiting.','Earn an item for this slot through a promotion challenge.'));return;}
 case 'gear-choice':{const o=state.gearOffers.find(o=>o.id===d.id);if(!o||o.claimed)throw Error('This choice is no longer available.');dialog('Choose your reward',`<p>One item for ${e(o.skillName)} level ${o.rank}. Your choice is permanent; neither variant costs credits.</p><div class="equal-col">${[0,1].map(v=>{const i=makeGear(o,v);return `<div class="card item-card"><span class="skill-icon gold">${icon('equipment')}</span><h3>${e(i.name)}</h3><p>${SLOT_LABELS[i.slot]}</p><div class="effect">${e(effectText(i))}</div><p class="small mt">${i.active?'Includes Deep Focus active ability.':'Passive effect while equipped.'}</p>${btn('Choose this item','choose-gear','data-id="'+e(o.id)+'" data-variant="'+v+'"','small primary')}</div>`;}).join('')}</div>`);return;}
 case 'choose-gear':await mutate(s=>E.chooseGear(s,d.id,Number(d.variant)),'Reward added to your inventory.');closeDialog();return;
 case 'item':itemDialog(d.id);return;
 case 'equip':{const i=state.inventory.find(i=>i.id===d.id);await mutate(s=>E.equip(s,i.id,i.slot),'Item equipped.');itemDialog(d.id);return;}
 case 'unequip':await mutate(s=>E.equip(s,null,d.id),'Item unequipped.');closeDialog();return;
 case 'activate-warning':{const item=state.inventory.find(i=>i.id===d.id),end=new Date(Date.now()+30*86400000);dialog('Activate Deep Focus?',`<p><strong>${e(item.name)}</strong><br>+100% ${e(item.skillId==='character'?'all skills':skillById(state,item.skillId)?.name||'skill')} XP for 24 hours.</p><div class="callout warning"><strong>This item and its ${SLOT_LABELS[item.slot].toLowerCase()} slot will be locked until ${e(end.toLocaleString())}.</strong> You cannot unequip or replace it during the full 30-day cooldown, even after the one-day effect ends. Changing classes will not release it. It unlocks automatically when the timer ends.</div><form id="activate-form"><input type="hidden" name="id" value="${e(item.id)}"><label class="check"><input type="checkbox" name="confirmed" required><span>I understand and accept the full 30-day equipment lock.</span></label>${formError}<div class="form-actions">${btn('Keep it ready','close','','ghost')}<button class="btn primary" type="submit">Activate & lock item</button></div></form>`);return;}
 case 'shop':{const o=shopOffers().find(x=>x.key===d.id);dialog('Add to your loadout',`<h3>${e(o.name)}</h3><p>${e(effectText(makeGear(o,o.variant)))}</p><div class="shop-price">${num(o.priceCents/100)} credits</div><p class="small">A virtual item. This spends credits without changing your skill or character XP. Purchase does not activate its ability.</p><form id="shop-form"><input name="key" type="hidden" value="${e(o.key)}"><label class="field"><span>Attune to a skill</span><select name="skillId">${skillOptions(o.skillId)}</select></label>${formError}<div class="form-actions"><button class="btn primary" type="submit" ${p.creditsCents<o.priceCents?'disabled':''}>Buy item</button></div></form>`);return;}
 case 'redeem-credits':dialog('Permission for a little reward',`<p>Choose a self-funded treat or experience. One credit represents roughly one dollar of purchase permission.</p><form id="redeem-form"><label class="field"><span>Reward</span><input name="title" maxlength="160" placeholder="A new book, a meal out, an experience…" required></label><label class="field"><span>Cost in credits</span><input name="credits" type="number" min=".01" step=".01" max="${p.creditsCents/100}" required><small>${num(p.creditsCents/100)} credits available. No payment is made by the app.</small></label>${formError}<div class="form-actions"><button class="btn primary" type="submit">Record redemption</button></div></form>`);return;
 case 'permission':{const r=state.permissions.find(r=>r.id===d.id);dialog('Your earned permission',`<span class="pill gold">Level ${r.rank} · Additional reward</span><h3 class="mt">${e(r.title)}</h3><div class="reward-value">${r.valueCents===null?'Unpriced':money(r.valueCents)}</div><p>This permission is extra to the credit shop. Mark it used when you choose or purchase your reward. It does not imply ownership.</p><form id="permission-form"><input name="id" type="hidden" value="${e(r.id)}"><label class="field"><span>Your chosen reward / substitution</span><input name="choice" maxlength="200" value="${e(r.choice||'')}" placeholder="What would feel meaningful to you?"></label><label class="field"><span>Status</span><select name="status">${[['available','Available'],['used','Used / purchased'],['passed','Passed over']].map(([v,l])=>option(v,l,r.status)).join('')}</select></label>${r.valueCents===null&&state.profile.annualIncomeCents?`<label class="check"><input type="checkbox" name="price"><span>Price this previously unpriced permission using my current income reference: ${money(E.rewardCents(r.rank,state.profile.annualIncomeCents))}.</span></label>`:''}${formError}<div class="form-actions"><button class="btn primary" type="submit">Save reward record</button></div></form>`);return;}
 case 'measurement':measurementDialog(d.id);return;
 case 'calculate-bmi':{const h=Number($('#height-in').value),w=Number($('#weight-lb').value);if(h<=0||w<=0)throw Error('Enter a positive height and weight.');const f=$('#measurement-form');f.elements.metric.value='bmi';updateMetricForm();f.elements.value.value=(w*.45359237/(h*.0254)**2).toFixed(2);return;}
 case 'source':{const s=SOURCES[d.id];if(s)dialog('Source & method',`<h3>${e(s.name)}</h3><span class="pill">${e(s.year)}</span><p class="mt">${e(s.method)}</p><div class="callout">${e(s.limitation)}</div><a class="btn ghost" href="${e(s.url)}" target="_blank" rel="noopener">Open original publication ↗</a>`);return;}
 case 'metric-history':{const metric=METRICS.find(m=>m.id===d.id),list=state.measurements.filter(m=>m.metric===d.id).sort((a,b)=>b.date.localeCompare(a.date));dialog(e(metric.name),`${btn('Add observation','measurement','data-id="'+d.id+'"','primary')}<div class="mt">${list.map(m=>`<div class="skill-row"><div class="grow"><strong>${num(m.value)} ${metric.unit}</strong><p class="small">${fmtDate(m.date)} · ${e(m.notes||'Manual observation')}</p></div>${btn('Correct','correct-metric','data-id="'+m.id+'"','text small')}</div>`).join('')}</div>`);return;}
 case 'correct-metric':{const m=state.measurements.find(m=>m.id===d.id);dialog('Correct an observation',`<p>The original value is preserved in the correction history.</p><form id="correct-metric-form"><input name="id" type="hidden" value="${e(m.id)}"><label class="field"><span>Correct value</span><input type="number" step="any" name="value" value="${m.value}" required></label><label class="field"><span>Reason</span><input name="reason" maxlength="300" required></label>${formError}<div class="form-actions"><button class="btn primary" type="submit">Save correction</button></div></form>`);return;}
 case 'photo':dialog('A moment worth keeping',`<img class="photo large" data-photo="${e(d.id)}" alt="Milestone photo">`,true);return;
 case 'entry':{const a=state.activities.find(a=>a.id===d.id);dialog('Activity record',`<h3>${e(a.title)}</h3><p>${fmtDate(a.date)} · ${e(skillById(state,a.skillId)?.name)}<br>${E.formatXP(p.awards.get(a.id)||0n)} XP · ${a.late?'Late, half base XP':'Timely entry'}</p><p>${e(a.notes)}</p><div class="photos">${a.photos.map(photoThumb).join('')}</div><div class="divider"></div><p class="small">If this entry is wrong, void it and record a correction. Voiding recalculates current and character XP; already-issued gear and milestone history remain. Entries supporting completed quests need that quest’s rewards resolved first.</p>${btn('Void incorrect entry','void-warning','data-id="'+e(a.id)+'"','danger small')}`);return;}
 case 'void-warning':dialog('Void this activity?',`<div class="callout warning">This removes its XP and qualifying quest progress. The original entry remains in the audit history. Export a backup first if you may need to restore the exact prior state.</div><div class="form-actions">${btn('Keep entry','close','','ghost')}${btn('Void entry','confirm-void','data-id="'+e(d.id)+'"','danger')}</div>`);return;
 case 'void-quest':dialog('Correct a quest completion',`<div class="callout warning">This returns the completion credits and removes the quest bonus XP. Your original activities, passed gateways and milestone history remain. The quest stays in history as voided. If its credits have been spent, earn enough to return the bonus first.</div><div class="form-actions">${btn('Keep completion','close','','ghost')}${btn('Void completion','confirm-void-quest','data-id="'+e(d.id)+'"','danger')}</div>`);return;
 case 'confirm-void-quest':await mutate(s=>E.voidQuestCompletion(s,d.id),'Completion voided. You can now correct its activity entries.');closeDialog();return;
 case 'confirm-void':await mutate(s=>E.voidActivity(s,d.id),'Entry voided; original retained in history.');closeDialog();return;
 case 'custom-skill':dialog('Chart your own skill',`<form id="custom-form"><label class="field"><span>Substantial skill name</span><input name="name" maxlength="80" required></label><label class="field"><span>Category</span><select name="category">${CATEGORIES.map(c=>option(c.id,c.name,'thinking')).join('')}</select></label><label class="field"><span>Main attribute</span><select name="attribute">${ATTRIBUTES.map(a=>option(a,a,'Intellect')).join('')}</select></label><p class="small">Your custom skill receives the same 50-level progression, challenges, and rewards. Add narrow techniques as notes or specialties within a broader skill.</p>${formError}<div class="form-actions"><button class="btn primary" type="submit">Add skill</button></div></form>`);return;
 case 'export':await exportBackup();return;
 case 'raw-export':download(await DB.exportRecoveryBundle(),'human-rpg-recovery-'+new Date().toISOString().slice(0,10)+'.json');toast('Raw recovery copy exported. Keep it for recovery; it is not a validated character backup.');return;
 case 'import':$('#restore-file').value='';$('#restore-file').click();return;
 case 'recover':{const r=await DB.recoveryInfo();if(!r)throw Error('No pre-restore recovery copy is available.');dialog('Undo the last restore?',`<div class="callout warning">This replaces your current character with the saved pre-restore copy. Newer changes will move into the recovery slot, allowing you to switch back. Export a backup first to preserve an independent copy.</div><p>Recover <strong>${e(r.name)}</strong> from ${fmtDate(r.savedAt)}.</p><form id="recover-form"><label class="check"><input type="checkbox" name="confirmed" required><span>I understand the current character will be replaced.</span></label>${formError}<div class="form-actions"><button class="btn primary" type="submit">Recover previous character</button></div></form>`);return;}
 case 'persist':{const granted=await DB.requestPersistence();storageInfo=await DB.storageStatus();render();toast(granted?'Persistent storage granted. Keep exporting backups.':'This browser did not grant persistence. Full backups remain available.');return;}
 case 'install':if(installPrompt){await installPrompt.prompt();installPrompt=null;render();}return;
 case 'rankings':rankingsDialog(d.id);return;
 case 'ranking-record':rankingRecordDialog(d.id);return;
 case 'rowing-calc':performanceDialog('rowing');return;
 case 'swimming-calc':performanceDialog('swimming');return;
 case 'ranking-void':await mutate(s=>{const r=s.rankingResults.find(r=>r.id===d.id);r.voided=true;s.audit.push({id:E.uid(),type:'ranking-voided',resultId:r.id,date:new Date().toISOString()});},'Result voided; original preserved.');rankingsDialog();return;
 }
}
function updateMetricForm(){const f=$('#measurement-form');if(!f)return;const m=METRICS.find(x=>x.id===f.elements.metric.value);$('#metric-value-label').textContent='Value · '+m.unit;f.elements.value.min=m.min;f.elements.value.max=m.max;}
function rankingsDialog(skillId=''){
 const skill=skillById(state,skillId),coverage=skill?coverageFor(skill):null,sources=coverage?.sources||RANKING_SOURCES,summary=coverageSummary();
 const records=(state.rankingResults||[]).filter(r=>!r.voided&&(!skill||r.skillId===skill.id)).slice().reverse();
 dialog(skill?e(skill.name)+' · real-world standards':'Rankings & standards',`<p>Every catalog skill has a coverage record. ${summary.sources} researched sources cover ${summary.mapped} of ${summary.skills} catalog skills; remaining skills have explicit research gaps.</p><label class="field"><span>Explore a discipline</span><select id="ranking-skill-filter">${option('','All sources',skill?.id||'')}${skillOptions(skill?.id||'')}</select></label>${coverage?`<div class="callout">${e(coverage.note)}</div>`:''}<div class="flex wrap mt mb">${btn('Record a result','ranking-record','data-id="'+e(skill?.id||'')+'"','primary small')}${(!skill||skill.id==='rowing')?btn('RowErg comparison','rowing-calc','','small'):''}${(!skill||skill.id==='swimming')?btn('Swimming points','swimming-calc','','small'):''}</div><p class="source-note">Reviewed ${REVIEWED}. External links open only when you choose them. Results stay on this device. A qualification or competitor ranking is not a population percentile.</p><div class="stack">${sources.map(s=>`<details class="disclosure"><summary>${e(s.name)} <span class="pill">${TYPES[s.type]}</span></summary><p class="small">${e(s.cohort)}</p><p class="small">${e(s.limitation)}</p><p class="source-note">${e(s.status)}</p><a href="${e(s.url)}" target="_blank" rel="noopener">Original source ↗</a></details>`).join('')||empty('Build a meaningful record.','No comparable rank is identified in this review. Add a dated achievement, context and an evidence link.')}</div><h3 class="mt">Your recorded results</h3>${records.length?records.slice(0,20).map(r=>`<div class="quest-tile"><div class="flex between"><strong>${e(skillById(state,r.skillId)?.name)}</strong><span class="pill">${r.calculator?'Calculated reference':'Self-recorded'}</span></div><h3>${e(r.result)}</h3><p>${e(r.cohort)}</p><p class="source-note">${fmtDate(r.date)} · ${e(r.sourceName)}<br>${e(r.notes)}</p>${r.sourceUrl?`<a class="small" href="${e(r.sourceUrl)}" target="_blank" rel="noopener">Evidence / source ↗</a>`:''}${btn('Void incorrect result','ranking-void','data-id="'+e(r.id)+'"','text small')}</div>`).join(''):empty('Your evidence belongs here.','Keep official ratings, competition results, qualifications and measured performances with their reference group.')}<p class="source-note"><a href="./docs/RANKINGS.md" target="_blank" rel="noopener">Complete coverage register</a>. Evidence supports your challenge self-assessment; recording a result does not automatically create XP or certify a title.</p>`,true);
}
function rankingRecordDialog(skillId='',prefill={}){
 const skill=skillById(state,skillId)||skillById(state,'running');
 dialog('Keep a real-world result',`<form id="ranking-result-form"><label class="field"><span>Skill</span><select name="skillId">${skillOptions(skill.id)}</select></label><label class="field"><span>Result or qualification</span><input name="result" maxlength="300" value="${e(prefill.result||'')}" required placeholder="Example: FIDE standard rating 1820, or 8th of 120 finishers"></label><div class="form-grid"><label class="field"><span>Reference type</span><select name="type">${Object.entries(TYPES).map(([v,l])=>option(v,l,prefill.type||'competition')).join('')}</select></label><label class="field"><span>Result date</span><input name="date" type="date" max="${today()}" value="${today()}" required></label></div><label class="field"><span>Reference group / event / division</span><input name="cohort" maxlength="500" value="${e(prefill.cohort||'')}" required placeholder="Event, age/sex division, country, eligible field, date or edition"></label><label class="field"><span>Source or assessment name</span><input name="sourceName" maxlength="200" value="${e(prefill.sourceName||'')}" required></label><label class="field"><span>Original result or source URL (optional)</span><input name="sourceUrl" type="url" maxlength="2000" value="${e(prefill.sourceUrl||'')}" placeholder="https://…"></label><label class="field"><span>Context and limitations</span><textarea name="notes" maxlength="2000">${e(prefill.notes||'')}</textarea></label><p class="small">This is your own evidence record. A ranking among competitors stays labeled with that field; it does not become a rank among all people.</p>${formError}<div class="form-actions"><button class="btn primary" type="submit">Save result</button></div></form>`);
}
async function saveRankingResult(data){
 const result=String(data.result||'').trim(),cohort=String(data.cohort||'').trim(),sourceName=String(data.sourceName||'').trim(),url=String(data.sourceUrl||'').trim();
 if(!skillById(state,data.skillId)||!result||!cohort||!sourceName||!TYPES[data.type]||!E.validDay(data.date)||data.date>today())throw Error('Include a skill, result, source, reference group and valid date.');
 if(url&&!/^https?:\/\//i.test(url))throw Error('Use an http or https source URL.');
 await mutate(s=>{s.rankingResults=s.rankingResults||[];s.rankingResults.push({id:E.uid(),skillId:data.skillId,type:data.type,result:result.slice(0,300),cohort:cohort.slice(0,500),sourceName:sourceName.slice(0,200),sourceUrl:url.slice(0,2000),notes:String(data.notes||'').slice(0,2000),date:data.date,recordedAt:new Date().toISOString(),voided:false});},'Result saved with its reference group.');
}
function performanceDialog(kind){
 const row=kind==='rowing';
 dialog(row?'Your 2,000 m RowErg result':'Your swimming performance',`<form id="performance-form"><input name="kind" type="hidden" value="${kind}">${row?`<div class="callout">Compare with ${num(ROWING_SNAPSHOT.people)} submissions in the Concept2 2026 non-adaptive field. All ages, genders, weights and countries; verified and unverified results. This is a participant comparison.</div>`:`<div class="callout">World Aquatics ${SWIM_TABLE.edition} · 25 m pool only. Table valid ${SWIM_TABLE.from} through ${SWIM_TABLE.to}. Points are not percentiles.</div><label class="field mt"><span>Event</span><select name="event">${SWIM_EVENTS.map(v=>option(v,v,'100m Freestyle')).join('')}</select></label><label class="field"><span>Published competition division</span><select name="sex"><option value="male">Men</option><option value="female">Women</option></select></label>`}<label class="field mt"><span>Total time · seconds</span><input name="seconds" type="number" min="1" max="86400" step=".01" placeholder="${row?'475 (7 min 55 sec)':'90 (1 min 30 sec)'}" required></label><p class="small">Use the matching event and equipment. The comparison uses a frozen table, not a live ranking. No value is uploaded.</p>${formError}<div class="form-actions"><button class="btn primary" type="submit">Calculate comparison</button></div></form>`);
}
document.addEventListener('input',event=>{
 if(event.target.id==='skill-search'){const start=event.target.selectionStart;search=event.target.value;skillPage=0;render();$('#skill-search').focus();$('#skill-search').setSelectionRange(start,start);return;}
 if(event.target.closest('#log-form'))updateXPPreview();
 if(event.target.closest('#assess-form'))updateAssessment();
 if(event.target.closest('#quest-form'))updateQuestPreview();
});
document.addEventListener('change',async event=>{
 try{
 if(event.target.id==='ranking-skill-filter')rankingsDialog(event.target.value);
 if(event.target.id==='category-filter'){category=event.target.value;skillPage=0;render();}
 if(event.target.id==='skill-filter'){skillFilter=event.target.value;skillPage=0;render();}
 if(event.target.id==='reward-filter'){rewardFilter=event.target.value;rewardPage=0;render();}
 if(event.target.id==='restore-file'&&event.target.files[0])await prepareRestore(event.target.files[0]);
 if(event.target.closest('#measurement-form')&&event.target.name==='metric')updateMetricForm();
 }catch(err){showError(err);}
});
document.addEventListener('submit',async event=>{
 const f=event.target;if(!(f instanceof HTMLFormElement))return;event.preventDefault();if(f.dataset.saving)return;
 f.dataset.saving='yes';const submit=event.submitter;if(submit)submit.disabled=true;
 try{const data=Object.fromEntries(new FormData(f)),get=name=>f.elements[name]?.value;
 switch(f.getAttribute('id')){
 case 'onboard-form':{
 const name=data.name.trim();if(!name)throw Error('Choose a character name.');
 const next=E.createState({name,classId:data.classId,annualIncomeCents:Math.round(Number(data.income||0)*100),timeZone:Intl.DateTimeFormat().resolvedOptions().timeZone||'America/Chicago'});
 state=await DB.saveState(next,0);p=E.project(state);render();if(submit?.value==='assess')interestsDialog('assess');else toast('Your adventure begins.');break;}
 case 'log-form':{const photos=await photosFrom(f);await mutate(s=>E.logActivity(s,{...data,photos}),'Activity saved. Progress earned.');closeDialog();break;}
 case 'interests-form':await mutate(s=>{s.profile.interests=new FormData(f).getAll('interests');},'Interests updated. Every skill is still tracked.');if(data.next==='assess')assessmentDialog();else closeDialog();break;
 case 'assess-form':{
 const level=assessmentLevel(f);if(level>=30&&String(data.evidence||'').trim().length<30)throw Error('Describe the independent recognition supporting an expert or higher assessment.');
 await mutate(s=>{E.assessSkill(s,data.skillId,level);s.audit.at(-1).evidence=String(data.evidence||'').slice(0,4000);},'Skill assessed. Validate its challenge to earn gear.');
 dialog('Experience recorded',`<p>${e(skillById(state,data.skillId).name)} begins at <strong class="gold">level ${level}</strong>. Assess another skill to build a fuller picture of your character.</p><div class="form-actions">${btn('Assess another skill','assess','','primary')}${btn('Composite character','character-assess','','ghost')}${btn('Done for now','close','','ghost')}</div>`);break;}
 case 'start-challenge-form':await mutate(s=>E.startAttempt(s,data.skillId,Number(data.rank),Number(data.variant)),'Challenge started.');challengeDialog(data.skillId,Number(data.rank));break;
 case 'submit-challenge-form':{const photos=await photosFrom(f);await mutate(s=>E.submitAttempt(s,data.id,{notes:data.notes,photos}),'Result recorded. The rubric is now available.');const a=state.attempts.find(a=>a.id===data.id);challengeDialog(a.skillId,a.rank,a.id);break;}
 case 'pass-challenge-form':await mutate(s=>E.passAttempt(s,data.id,new FormData(f).getAll('criterion').map(()=>true)),'Milestone earned. Gear choices and purchase permission are ready.');closeDialog();break;
 case 'quest-form':await mutate(s=>E.createQuest(s,{...data,stakeCents:Math.round(Number(data.stake)*100),confirmed:data.confirmed==='on'}),'Quest accepted.');closeDialog();break;
 case 'activate-form':await mutate(s=>E.activateAbility(s,data.id,data.confirmed==='on'),'Deep Focus activated. Item locked for 30 days.');itemDialog(data.id);break;
 case 'shop-form':{const o=shopOffers().find(o=>o.key===data.key),skill=skillById(state,data.skillId);await mutate(s=>E.buyItem(s,{...o,skillId:skill.id,skillName:skill.name}),'Equipment purchased with reward credits.');closeDialog();break;}
 case 'redeem-form':{const cost=Math.round(Number(data.credits)*100);if(!Number.isSafeInteger(cost)||cost<=0||cost>p.creditsCents)throw Error('Enter an amount within your available credit balance.');await mutate(s=>E.addCredit(s,'redemption:'+E.uid(),-cost,'Personal reward: '+String(data.title).slice(0,160)),'Redemption recorded. Enjoy your reward.');closeDialog();break;}
 case 'permission-form':await mutate(s=>{const r=s.permissions.find(r=>r.id===data.id);E.usePermission(s,data.id,data.status);r.choice=String(data.choice||'').slice(0,200);r.updatedAt=new Date().toISOString();if(data.price==='on'&&r.valueCents===null){r.valueCents=E.rewardCents(r.rank,s.profile.annualIncomeCents);r.incomeCents=s.profile.annualIncomeCents;}s.audit.push({id:E.uid(),type:'permission-status',permissionId:r.id,status:r.status,date:r.updatedAt});},'Reward record updated.');closeDialog();break;
 case 'profile-form':await mutate(s=>{const name=data.name.trim();if(!name)throw Error('Choose a character name.');s.profile={...s.profile,name,classId:data.classId,annualIncomeCents:Math.round(Number(data.income)*100),age:data.age?Number(data.age):null,comparisonSex:data.comparisonSex};},'Character updated.');closeDialog();break;
 case 'measurement-form':{
 const m=METRICS.find(m=>m.id===data.metric),value=Number(data.value);if(!m||!Number.isFinite(value)||value<m.min||value>m.max||!E.validDay(data.date)||data.date>today())throw Error('Check the value and observation date.');
 if(data.metric==='cognitive-score'&&String(data.notes).trim().length<3)throw Error('Record the test name and edition so the score has context.');
 await mutate(s=>s.measurements.push({id:E.uid(),metric:m.id,value,date:data.date,age:data.age?Number(data.age):null,sex:data.sex,notes:String(data.notes).slice(0,2000),recordedAt:new Date().toISOString()}),'Observation recorded.');closeDialog();break;}
 case 'correct-metric-form':await mutate(s=>{const m=s.measurements.find(m=>m.id===data.id),spec=METRICS.find(x=>x.id===m.metric),value=Number(data.value);if(!Number.isFinite(value)||value<spec.min||value>spec.max)throw Error('Value is outside the supported range.');s.audit.push({id:E.uid(),type:'measurement-correction',measurementId:m.id,previous:m.value,next:value,reason:String(data.reason).slice(0,300),date:new Date().toISOString()});m.value=value;},'Observation corrected; original value preserved.');closeDialog();break;
 case 'custom-form':{let id;await mutate(s=>{id=E.addCustomSkill(s,data).id;},'Custom skill added.');detailId=id;view='skill';closeDialog();render();break;}
 case 'character-form':await mutate(s=>{const baseline=Number(data.baseline||0),rank=Number(data.rank);if(!s.baseline.characterLevel&&baseline){s.baseline.characterLevel=baseline;s.audit.push({id:E.uid(),type:'character-assessment',rank:baseline,notes:String(data.notes).slice(0,4000),date:new Date().toISOString()});}E.validateCharacter(s,rank);s.audit.at(-1).notes=String(data.notes).slice(0,4000);},'Character milestone validated.');closeDialog();break;
 case 'restore-form':if(!restorePayload||data.confirmed!=='on')throw Error('Select and confirm a valid backup.');state=await DB.restoreBackup(restorePayload,restoreRevision);restorePayload=null;photoUrls.clear();blocked=false;channel?.postMessage({revision:state.revision});view='dashboard';closeDialog();render();toast('Backup restored. Your prior character is in the recovery copy.');break;
 case 'recover-form':if(data.confirmed!=='on')throw Error('Confirm recovery first.');state=await DB.recoverPrevious(state?.revision??await DB.currentRevision());photoUrls.clear();blocked=false;channel?.postMessage({revision:state.revision});view='dashboard';closeDialog();render();toast('Previous character recovered.');break;
 case 'performance-form':{
 const seconds=Number(data.seconds),row=data.kind==='rowing';if(!Number.isFinite(seconds)||seconds<1||seconds>86400)throw Error('Enter a valid time in seconds.');
 const c=row?rowingComparison(seconds):swimmingPoints(data.event,data.sex,seconds);if(!c)throw Error('Select a supported event and reference division.');
 rankingRecordDialog(row?'rowing':'swimming',{result:seconds+' seconds · '+c.label,type:row?'participant':'competition',cohort:row?ROWING_SNAPSHOT.cohort:data.event+' · '+data.sex+' · 25 m pool · '+SWIM_TABLE.edition,sourceName:row?'Concept2 2026 snapshot, reviewed '+REVIEWED:'World Aquatics '+SWIM_TABLE.edition,sourceUrl:row?ROWING_SNAPSHOT.url:SWIM_TABLE.url,notes:row?'Published percentile boundaries only; no interpolation or tail extrapolation. Not a general-population or demographic-specific rank.':'Formula floor(1000 × (base time / result time)^3). Base time '+c.base+' seconds. Valid '+SWIM_TABLE.from+' to '+SWIM_TABLE.to+'. Points are not percentiles.'});break;}
 case 'ranking-result-form':await saveRankingResult(data);rankingsDialog(data.skillId);break;
 }
 }catch(err){showError(err,f);}finally{delete f.dataset.saving;if(submit?.isConnected)submit.disabled=false;}
});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});
async function refreshCalendar(){
 if(!state||busy||blocked)return;const next=E.clone(state);E.settleQuests(next);if(JSON.stringify(next.quests)!==JSON.stringify(state.quests))await mutate(()=>{});
 else if(!$('#modal').open&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))render();
}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshCalendar().catch(showError);});
setInterval(()=>refreshCalendar().catch(showError),60000);
async function init(){
 try{state=await DB.loadState();if(state){const draft=E.clone(state);E.settleQuests(draft);E.resolveRewards(draft);if(JSON.stringify(state)!==JSON.stringify(draft))state=await DB.saveState(draft,state.revision);}render();DB.storageStatus().then(info=>storageInfo=info).catch(()=>{});if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(()=>toast('Offline installation was unavailable. Local progress still saves.',true));}
 catch(err){$('#app').innerHTML=`<main id="main" class="fatal card"><div class="eyebrow">Your saved data has not been replaced</div><h1>We couldn’t open your character.</h1><p>${e(err.message)}</p><p>Reload this page or close other app tabs. If the stored data is damaged, keep it intact and use a known backup or the recovery copy.</p><div class="flex wrap">${btn('Reload','reload','','primary')}${btn('Export recovery data','raw-export','','ghost')}${btn('Restore backup','import','','ghost')}${btn('Recovery copy','recover','','ghost')}</div></main>`;}
}
init();
